<?php session_start();if(!isset($_SESSION['siswa'])&&!isset($_SESSION['admin'])){header('Location: ../auth/v_login.php');exit;}require_once '../../MODEL/m_histori.php';$h=new Histori();$data=isset($_SESSION['siswa'])?$h->getBySiswa((int)$_SESSION['nis']):$h->getAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Histori Aspirasi</title><link rel="stylesheet" href="../../ASSETS/modern.css"></head><body><main><a class="back" href="<?=isset($_SESSION['admin'])?'../ADMIN/v_dasbord_admin.php':'dasbord_siswa.php'?>">← Dashboard</a><div class="page-head"><div><h1>🕘 Histori Aspirasi</h1><p>Riwayat perubahan status dan feedback.</p></div></div><div class="table-card"><div class="table-wrap"><table><tr><th>ID</th><th>Aspirasi</th><th>NIS</th><th>Status</th><th>Feedback</th><th>Tanggal</th></tr><?php if(!$data):?><tr><td colspan="6" class="empty">Belum ada histori.</td></tr><?php endif;?><?php foreach($data as $r):?><tr><td>#<?=$r['id_histori']?></td><td>#<?=$r['id_aspirasi']?></td><td><?=$r['nis']?></td><td><span class="badge <?=strtolower($r['status'])==='proses'?'badge-proses':(strtolower($r['status'])==='selesai'?'badge-selesai':'badge-menunggu')?>"><?=htmlspecialchars($r['status'])?></span></td><td><?=htmlspecialchars($r['feedback']??'-')?></td><td><?=htmlspecialchars($r['tanggal'])?></td></tr><?php endforeach;?></table></div></div></main></body></html>